		}(),
		flags.UserDataDir: DefaultUserDataDirPrefix,
	}

	return &Manager{
		Logger:   utils.LoggerQuiet,
		Defaults: func(_ http.ResponseWriter, _ *http.Request) *Launcher { return New() },
