174: // IdleCounter is similar to sync.WaitGroup but it only resolves if no jobs for specified duration.
175: type IdleCounter struct {
176: 	lock     *sync.Mutex
177: 	job      int
178: 	duration time.Duration
179: 	tmr      *time.Timer
180: }
181: 
182: // NewIdleCounter ...
183: func NewIdleCounter(d time.Duration) *IdleCounter {
184: 	tmr := time.NewTimer(time.Hour)
185: 	tmr.Stop()
186: 
187: 	return &IdleCounter{
188: 		lock:     &sync.Mutex{},
189: 		duration: d,
190: 		tmr:      tmr,
191: 	}
192: }
193: 
194: // Add ...
195: func (de *IdleCounter) Add() {
196: 	de.lock.Lock()
197: 	defer de.lock.Unlock()
198: 
199: 	de.tmr.Stop()
200: 	de.job++
201: }
202: 
203: // Done ...
204: func (de *IdleCounter) Done() {
205: 	de.lock.Lock()
206: 	defer de.lock.Unlock()
207: 
208: 	de.job--
209: 	if de.job == 0 {
210: 		de.reset(de.duration)
211: 	}
212: 	if de.job < 0 {
213: 		panic("all jobs are already done")
214: 	}
215: }
216: 
217: // Wait ...
218: func (de *IdleCounter) Wait(ctx context.Context) {
219: 	de.lock.Lock()
220: 	if de.job == 0 {
221: 		de.reset(de.duration)
222: 	}
223: 	de.lock.Unlock()
224: 
225: 	select {
226: 	case <-ctx.Done():
227: 		de.tmr.Stop()
228: 	case <-de.tmr.C:
229: 	}
230: }
