232: func (de *IdleCounter) reset(d time.Duration) {
233: 	if !de.tmr.Stop() {
234: 		select {
235: 		case <-de.tmr.C:
236: 		default:
237: 		}
238: 	}
239: 	de.tmr.Reset(d)
240: }
