func (p *Page) ScrollScreenshot(opt *ScrollScreenshotOptions) ([]byte, error) {
	if opt == nil {
		opt = &ScrollScreenshotOptions{}
	}
	if opt.WaitPerScroll == 0 {
		opt.WaitPerScroll = time.Millisecond * 300
