			}
		}

		req := &proto.PageCaptureScreenshot{
			Format:                opt.Format,
			Quality:               opt.Quality,
			Clip:                  clip,
			FromSurface:           false,
			CaptureBeyondViewport: false,
			OptimizeForSpeed:      false,
		}
		shot, err := req.Call(p)
		if err != nil {
			return nil, err
		}

